74	\begin{definition}[Low individual degree polynomials]\label{def:polyfunc}
75		\lean{MIPStarRE.LDT.Preliminaries.polyFunc, MIPStarRE.LDT.Polynomial}
76		\leanok
77		Let $\polyfunc{m}{q}{d}$ be the set of polynomials $g \in \F_q[x_1,\dots,x_m]$ whose degree in each variable is at most $d$, viewed as functions $\F_q^m \to \F_q$ via evaluation. (Over finite fields, distinct low-degree polynomials can induce the same function; we identify elements of $\polyfunc{m}{q}{d}$ with their polynomial representatives, not their functional equivalence classes.)
78	\end{definition}
79	
80	\begin{remark}[Individual-degree convention]\label{rem:individual-degree-convention}
81		Here, ``individual degree $d$'' means degree at most $d$ in each coordinate. In
82		particular,
83		\[
84			\polyfunc{m}{q}{d} \subseteq \polyfunc{m}{q}{d+1}.
85		\]

